  "description": "Browsing agent for Aux browser",
  "key": "",
  "icons": {
    "16": "icons/icon-16.png",
    "48": "icons/icon-48.png",
    "128": "icons/icon-128.png"
  },
  "action": {
    "default_title": "Aux Browsing Agent"
  },
  "side_panel": {
    "default_path": "sidepanel.html"
  },
  "chrome_url_overrides": {
    "newtab": "newtab.html"
  },
  "permissions": [
    "sidePanel",
    "contextMenus",
    "storage",
    "activeTab",
    "tabCapture",
    "offscreen",
    "debugger",
    "downloads",
    "favicon",
    "history",
    "bookmarks",
    "topSites",
    "browsingData",
    "privacy",
    "management",
    "nativeMessaging",
    "cookies",
    "tabs",
    "scripting",
    "userScripts",
    "webNavigation",
    "sessions",
    "tabGroups",
    "alarms",
    "notifications",
    "dev.aux.blink.expose-wv",
    "dev.aux.ext.private.account",
    "dev.aux.ext.private.adblock",
    "dev.aux.ext.private.browserImport",
    "dev.aux.ext.private.notification",
    "dev.aux.ext.private.omnibox",
    "dev.aux.ext.private.browserPreferences",
    "dev.aux.ext.private.miniPopup",
    "dev.aux.ext.private.capture-tab-without-userinteraction",
